import {test,type Page} from '@playwright/test';
const expectedTitles=new WeakMap<Page,string>();
const clients=new WeakMap<Page,{errors:string[];failedRequests:string[];mutationRequests:number;mainNavigations:number;commandPhases:Record<string,boolean>;commandDocumentChanged:boolean}>();
export function expectGapUiTitle(page:Page,title:string){expectedTitles.set(page,title);}
const traces=new WeakMap<Page,Array<{route:string;method:string;status:number;denial?:string}>>();
const projections=new WeakMap<Page,{working:string;reviewed:string;workingContent:boolean;reviewedContent:boolean;expectedTitleMatches?:boolean}>();
const signals=['Product gaps are unavailable','Loading current product gaps','The view changed','Record changed','Content: withheld','Content: eligible','No reviewed revision yet.','Request unconfirmed','Preparation: prepared'] as const;
function routeKind(path:string){if(path==='/api/auth/session')return 'session';if(path==='/api/auth/login')return 'login';if(!path.startsWith('/api/product-gaps'))return null;if(path.includes('/canonicalization/'))return 'canonicalization';if(path.includes('/reports/')){for(const suffix of ['handoffs','previews','decisions','cancel','exports'])if(path.includes('/'+suffix))return 'report-'+suffix;return 'report-detail';}if(path.endsWith('/reports'))return 'report-registry';if(path.includes('/requests/'))return 'request-status';if(path.endsWith('/workloads'))return 'customer-workloads';if(path.endsWith('/evidence'))return 'evidence';for(const suffix of ['impacts','revisions','previews','decisions'])if(path.includes('/'+suffix))return 'gap-'+suffix;return path==='/api/product-gaps'?'gap-registry':'gap-detail';}
export function installGapUiDiagnostics(){test.beforeEach(async({page})=>{await page.addInitScript(()=>{
 const counts={focus:0,blur:0,hidden:0,visible:0,submits:0,invalidEvents:0,gapSubmits:0,gapBubble:0,gapPreventedBubble:0,gapPreventedMicrotask:0,gapDisconnectedMicrotask:0,gapReactHandlerPresent:0};
 Object.defineProperty(window,'__turasGapUiLifecycle',{value:counts});
 window.addEventListener('focus',()=>counts.focus++);window.addEventListener('blur',()=>counts.blur++);
 document.addEventListener('visibilitychange',()=>{if(document.hidden)counts.hidden++;else counts.visible++;});
 document.addEventListener('submit',event=>{counts.submits++;const form=event.target;if(!(form instanceof HTMLFormElement)||!form.matches('.gap-form'))return;counts.gapSubmits++;const key=Object.keys(form).find(key=>key.startsWith('__reactProps'));if(key&&typeof (form as unknown as Record<string,{onSubmit?:unknown}>)[key]?.onSubmit==='function')counts.gapReactHandlerPresent++;queueMicrotask(()=>{if(event.defaultPrevented)counts.gapPreventedMicrotask++;if(!form.isConnected)counts.gapDisconnectedMicrotask++;});},true);
 document.addEventListener('submit',event=>{if(event.target instanceof HTMLFormElement&&event.target.matches('.gap-form')){counts.gapBubble++;if(event.defaultPrevented)counts.gapPreventedBubble++;}});document.addEventListener('invalid',()=>counts.invalidEvents++,true);
 });const trace:Array<{route:string;method:string;status:number;denial?:string}>=[];traces.set(page,trace);const client={errors:[] as string[],failedRequests:[] as string[],mutationRequests:0,mainNavigations:0,commandPhases:{} as Record<string,boolean>,commandDocumentChanged:false};clients.set(page,client);page.on('console',message=>{const match=/^GAP_COMMAND_PHASE:(fetchEntered|responseReturned|jsonEntered|jsonFailed|jsonCompleted|bodyHeld|transportFinished)$/.exec(message.text());if(match)client.commandPhases[match[1]]=true;});page.on('request',request=>{if(request.method()==='POST'&&routeKind(new URL(request.url()).pathname)?.startsWith('gap-'))client.mutationRequests++;});page.on('framenavigated',frame=>{if(frame===page.mainFrame()){client.mainNavigations++;if(client.commandPhases.fetchEntered)client.commandDocumentChanged=true;}});page.on('pageerror',error=>{const text=String(error);client.errors.push(/ChunkLoadError|Loading chunk/i.test(text)?'chunk_load':/hydrat/i.test(text)?'hydration':error.name==='TypeError'?'type':error.name==='ReferenceError'?'reference':error.name==='SyntaxError'?'syntax':'other');if(client.errors.length>10)client.errors.shift();});page.on('requestfailed',request=>{const route=routeKind(new URL(request.url()).pathname);if(route){client.failedRequests.push(route);if(client.failedRequests.length>30)client.failedRequests.shift();}});page.on('response',async response=>{const route=routeKind(new URL(response.url()).pathname),method=response.request().method();if(route&&['GET','POST','PUT','DELETE','PATCH'].includes(method)){const entry:{route:string;method:string;status:number;denial?:string}={route,method,status:response.status()};trace.push(entry);if(response.status()===409)try{const body=await response.body();if(body.length<=65536){const message=JSON.parse(body.toString()).error?.message;const known:Record<string,string>={'Critical original evidence required':'missing_originals','Confirmation needs known date and product context':'missing_date_or_product','Review a current eligible gap first':'review_unavailable','Record changed':'version_conflict'};entry.denial=(Object.hasOwn(known,message)?known[message]:'other_conflict');}}catch{/* Only fixed denial categories are retained. */}if(trace.length>30)trace.shift();}
 if(route==='gap-detail'&&method==='GET'&&response.status()===200)try{const body=await response.body();if(body.length>1048576)return;const data=JSON.parse(body.toString()).data;const state=(revision:unknown)=>{if(revision===null)return 'absent';const value=(revision as {availability?:unknown}|undefined)?.availability;return typeof value==='string'&&['eligible','withheld','expired','disabled'].includes(value)?value:'unknown';};projections.set(page,{working:state(data?.working),reviewed:state(data?.reviewed),workingContent:!!data?.working?.content,reviewedContent:!!data?.reviewed?.content,...(expectedTitles.has(page)?{expectedTitleMatches:data?.working?.content?.title===expectedTitles.get(page)}:{})});}catch{/* A missing diagnostic never proves an available projection. */}
 });});
test.afterEach(async({page},info)=>{if(info.status===info.expectedStatus)return;const text=await page.locator('body').innerText({timeout:1000}).catch(()=>'');const interaction=await page.evaluate(()=>{
 const names=['observedAt','resolvedAt','consequences','workaroundBurden','severityRationale','title','problem','workflow','desiredOutcome'];
 const controls=Array.from(document.querySelectorAll<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>('form input,form textarea,form select')).filter(control=>names.includes(control.name)).slice(0,30).map(control=>({name:control.name,valuePresent:!!control.value,valid:control.validity.valid,valueMissing:control.validity.valueMissing,badInput:control.validity.badInput,typeMismatch:control.validity.typeMismatch,stepMismatch:control.validity.stepMismatch}));
 const submits=Array.from(document.querySelectorAll<HTMLButtonElement>('.gap-form button[type=submit]'));const impact=submits.some(button=>button.form?.querySelector('[name=observedAt]'));const submit=submits[0];
 const alerts=Array.from(document.querySelectorAll('[role=alert]')).slice(0,5).map(element=>{const message=element.textContent??'';return message.includes('"code"')&&message.includes('"path"')?'schema_validation':message.includes('Critical original evidence required')?'known_domain_denial':'other';});
 return {counts:(window as unknown as {__turasGapUiLifecycle?:Record<string,number>}).__turasGapUiLifecycle,controls,impactFormPresent:impact,submitDisabled:submit?.disabled??false,alerts};
 }).catch(()=>undefined);console.log('GAP_UI_FIXED_DIAGNOSTIC '+JSON.stringify({interaction,responses:traces.get(page)??[],signals:signals.filter(signal=>text.includes(signal)),projection:projections.get(page),client:clients.get(page),...(expectedTitles.has(page)?{expectedHeadingPresent:await page.getByRole('heading',{name:expectedTitles.get(page),exact:true}).count().then(count=>count===1).catch(()=>false)}:{})}));});
}
